//! The platform layer of `kube apple`: k3s configuration (registries, embedded registry mirror, CIS hardening, bundled
//! add-on profile, Cilium) generated by the `kube addons` generators and delivered to the nodes of an existing cluster over
//! the same pinned ssh connections as the rest of `kube apple`.
//!
//! Everything the nodes are asked to do goes through [`Remote`], which has one real implementation over [`Host`] and a
//! recording fake in the tests. Plans are pure; nothing here reads the network.

use super::host::Host;
use super::model::*;
use super::script::{self, SERVER_DIR};
use super::script_ha::DROPIN_DIR;
use crate::kube_addons::{self, K3sConfig};
use crate::kube_harden::{self, GuestFile};
use anyhow::{Context, Result, bail};
use std::path::{Path, PathBuf};

/// Our own k3s drop-in. k3s merges `config.yaml.d/*.yaml` with `config.yaml`; a drop-in keeps the user's `config.yaml` untouched.
pub const PLATFORM_DROPIN: &str = "/etc/rancher/k3s/config.yaml.d/40-fluxvm-platform.yaml";
pub use crate::kube_registry::REGISTRIES_PATH;

const READY_POLLS: u32 = 60;
const POLL_SECS: u64 = 5;

// ---------------------------------------------------------------- what the nodes are asked to do

/// The few things platform operations need from a cluster. [`HostRemote`] is the real one.
#[allow(async_fn_in_trait)]
pub trait Remote {
    /// Every node as `(name, role)`, servers first.
    fn nodes(&self) -> Vec<(String, Role)>;
    /// Runs a script on a node (stdin optional) and returns stdout. A non-zero exit is an error.
    async fn run(&self, node: &str, script: &str, stdin: Option<&[u8]>) -> Result<String>;
    async fn pause(&self, secs: u64);
    /// `YYYYMMDD-HHMMSS`.
    fn stamp(&self) -> String;

    fn servers(&self) -> Vec<String> {
        self.nodes().into_iter().filter(|(_, r)| *r == Role::Server).map(|(n, _)| n).collect()
    }
    /// Runs a script on the first server that answers.
    async fn run_server(&self, script: &str, stdin: Option<&[u8]>) -> Result<String> {
        let mut last = None;
        for s in self.servers() {
            match self.run(&s, script, stdin).await {
                Ok(o) => return Ok(o),
                Err(e) => last = Some(e),
            }
        }
        Err(last.unwrap_or_else(|| anyhow::anyhow!("this record has no local server node")))
    }
}

pub struct HostRemote<'a, H: Host> {
    pub h: &'a H,
    pub st: &'a State,
}

impl<H: Host> Remote for HostRemote<'_, H> {
    fn nodes(&self) -> Vec<(String, Role)> {
        self.st.ordered().iter().map(|n| (n.name.clone(), n.role)).collect()
    }
    async fn run(&self, node: &str, script: &str, stdin: Option<&[u8]>) -> Result<String> {
        let out = self.h.ssh(self.st, node, script, stdin).await?;
        Ok(String::from_utf8_lossy(&out).trim().to_owned())
    }
    async fn pause(&self, secs: u64) {
        self.h.pause(secs).await
    }
    fn stamp(&self) -> String {
        self.h.stamp()
    }
}

fn path_ok(p: &str) -> bool {
    p.starts_with('/') && p.bytes().all(|b| b.is_ascii_alphanumeric() || b"/._-".contains(&b)) && !p.contains("..")
}

/// A script that receives a file on stdin and installs it root-owned with `mode`, creating its directory.
pub fn write_file_script(path: &str, mode: &str) -> String {
    assert!(path_ok(path), "unsafe path {path}");
    assert!(mode.len() == 4 && mode.bytes().all(|b| (b'0'..=b'7').contains(&b)));
    format!(": fluxvm-op platform-write; set -eu; sudo -n install -D -m {mode} /dev/stdin {path}")
}

pub async fn put<R: Remote>(r: &R, node: &str, path: &str, mode: &str, content: &str) -> Result<()> {
    r.run(node, &write_file_script(path, mode), Some(content.as_bytes())).await?;
    Ok(())
}

/// Restarts k3s on a node and waits until it is active (and, on a server, its API says ready).
pub async fn restart_and_wait<R: Remote>(r: &R, node: &str, role: Role) -> Result<()> {
    r.run(node, &format!(": fluxvm-op platform-restart; set -eu; sudo -n systemctl restart {}.service", role.unit()), None).await?;
    wait_up(r, node, role).await
}

/// Waits until k3s is active on a node (and, on a server, its API says ready).
pub async fn wait_up<R: Remote>(r: &R, node: &str, role: Role) -> Result<()> {
    let mut last = String::from("no answer");
    for _ in 0..READY_POLLS {
        let active = r.run(node, &script::is_active_script(role), None).await;
        match (role, active) {
            (_, Err(e)) => last = e.to_string(),
            (Role::Agent, Ok(a)) if a.trim() == "active" => return Ok(()),
            (Role::Server, Ok(a)) if a.trim() == "active" => match r.run(node, &script::readyz_script(), None).await {
                Ok(o) if o.trim() == "ok" => return Ok(()),
                Ok(o) => last = format!("readyz: {o}"),
                Err(e) => last = e.to_string(),
            },
            (_, Ok(a)) => last = format!("service is {a}"),
        }
        r.pause(POLL_SECS).await;
    }
    bail!("{node} did not come up: {last}")
}

// ---------------------------------------------------------------- the plan

/// Bundled-component profiles for `--addons`.
pub const ADDON_PROFILES: [&str; 4] = ["default", "minimal", "metallb", "envoy-gateway"];

/// The profile that also installs Envoy Gateway (pinned) once the cluster is up.
pub const ENVOY_GATEWAY_PROFILE: &str = "envoy-gateway";

/// The components a profile turns off (Traefik is always off in `kube apple`).
pub fn profile_disables(profile: &str) -> Result<Vec<String>> {
    Ok(match profile {
        "default" => vec![],
        // Nothing bundled but CoreDNS: bring your own load balancer, storage and metrics.
        "minimal" => vec!["servicelb".into(), "local-storage".into(), "metrics-server".into()],
        // MetalLB replaces ServiceLB.
        "metallb" => vec!["servicelb".into()],
        // Nothing is turned off: Envoy's LoadBalancer Services are answered by ServiceLB. Envoy Gateway itself is installed
        // after create (see `PlatformPlan::install`).
        "envoy-gateway" => vec![],
        other => bail!("--addons {other:?} must be one of: {}", ADDON_PROFILES.join(", ")),
    })
}

#[derive(clap::Args, Debug, Default, Clone)]
pub struct PlatformArgs {
    /// A `registries.yaml` (mirrors and registry credentials) copied to every node. Checked to be YAML with only `mirrors` and `configs`.
    #[arg(long, value_name = "FILE")]
    pub registries_file: Option<PathBuf>,
    /// Turn on k3s's embedded registry mirror (Spegel) on the servers. Without --registries-file a `mirrors: {"*": {}}`
    /// registries.yaml is written for you.
    #[arg(long)]
    pub embedded_registry: bool,
    /// Hardening profile: `cis` writes the k3s CIS settings, the sysctls, a Pod Security Admission file and an audit policy.
    #[arg(long, value_parser = ["cis"])]
    pub harden: Option<String>,
    /// With --harden cis: the cluster-wide Pod Security level (default restricted; kube-system is exempt).
    #[arg(long, value_parser = ["baseline", "restricted"], requires = "harden")]
    pub psa_level: Option<String>,
    /// Bundled add-on profile: default (k3s as shipped), minimal (no ServiceLB, local-storage or metrics-server), metallb (no ServiceLB), envoy-gateway (as shipped, and Envoy Gateway installed from a pinned manifest after create).
    #[arg(long, value_parser = ADDON_PROFILES)]
    pub addons: Option<String>,
    /// Make room for Cilium: no flannel, no k3s network policy. Cilium is installed by you afterwards (a command is printed).
    #[arg(long)]
    pub cilium: bool,
    /// With --cilium: also disable kube-proxy.
    #[arg(long, requires = "cilium")]
    pub cilium_kube_proxy_replacement: bool,
}

impl PlatformArgs {
    pub fn is_empty(&self) -> bool {
        self.registries_file.is_none()
            && !self.embedded_registry
            && self.harden.is_none()
            && self.addons.is_none()
            && !self.cilium
    }
}

/// The Cilium chart version the printed install command uses. Not installed by this tool.
pub const CILIUM_VERSION: &str = "1.20.5";

#[derive(Debug, Clone, Default, PartialEq)]
pub struct PlatformPlan {
    /// The drop-in for the servers; `None` when there is nothing to configure.
    pub dropin: Option<String>,
    /// Files for every node.
    pub all_files: Vec<GuestFile>,
    /// Files for the servers (hardening).
    pub server_files: Vec<GuestFile>,
    /// Components the profile disables: merged into the cluster's shared flags by `create`, and checked by `apply`.
    pub disable: Vec<String>,
    /// Pinned add-ons to install once the cluster is up (`create` only): `envoy-gateway`.
    pub install: Vec<String>,
    pub notes: Vec<String>,
}

/// Reads and checks a `registries.yaml`. k3s ignores unknown keys silently, so a typo would otherwise do nothing.
pub fn read_registries(path: &Path) -> Result<String> {
    let meta = std::fs::metadata(path).with_context(|| format!("reading {}", path.display()))?;
    if meta.len() > 256 * 1024 {
        bail!("{} is larger than 256 KiB", path.display());
    }
    let text = std::fs::read_to_string(path).with_context(|| format!("reading {}", path.display()))?;
    check_registries(&text)?;
    Ok(text)
}

pub fn check_registries(text: &str) -> Result<()> {
    let v: serde_yaml::Value = serde_yaml::from_str(text).context("registries file is not valid YAML")?;
    let m = v.as_mapping().context("registries file must be a YAML mapping")?;
    if m.is_empty() {
        bail!("registries file is empty");
    }
    for k in m.keys() {
        match k.as_str() {
            Some("mirrors" | "configs") => {}
            other => bail!("registries file key {other:?} is not one k3s reads (mirrors, configs)"),
        }
    }
    Ok(())
}

fn has_mirrors(text: &str) -> bool {
    serde_yaml::from_str::<serde_yaml::Value>(text).ok().is_some_and(|v| v.get("mirrors").is_some())
}

/// Everything the flags ask for, as data. `registries` is the content of `--registries-file`, already read.
pub fn plan(a: &PlatformArgs, registries: Option<&str>) -> Result<PlatformPlan> {
    let mut p = PlatformPlan::default();
    let mut c = K3sConfig::default();
    if let Some(prof) = &a.addons {
        p.disable = profile_disables(prof)?;
        if prof == ENVOY_GATEWAY_PROFILE {
            p.install.push("envoy-gateway".into());
        }
    }
    if a.cilium {
        c.merge(&kube_addons::cilium(a.cilium_kube_proxy_replacement)?)?;
        p.notes.push(format!(
            "Cilium is not installed by k3s. After the nodes restart they have no pod network until you run:\n{}",
            kube_addons::cilium_install_hint(CILIUM_VERSION, "127.0.0.1", a.cilium_kube_proxy_replacement).trim_end()
        ));
    }
    let mut reg = registries.map(str::to_owned);
    if a.embedded_registry {
        c.set_bool("embedded-registry", true)?;
        match &reg {
            None => {
                reg = Some(kube_registry_embedded_all()?);
                p.notes.push("wrote a registries.yaml that sends every registry through the embedded mirror; nodes need TCP 5001 and 6443 open to each other".into());
            }
            Some(t) if !has_mirrors(t) => {
                bail!("--embedded-registry needs the registries file to have a `mirrors:` entry for the registries to serve (for example `mirrors: {{\"*\": {{}}}}`)")
            }
            Some(_) => {}
        }
    }
    if let Some(r) = reg {
        p.all_files.push(GuestFile { path: REGISTRIES_PATH.into(), mode: "0600", content: r });
    }
    if let Some(h) = &a.harden {
        assert_eq!(h, "cis");
        c.merge(&kube_harden::cis_config())?;
        let level = a.psa_level.as_deref().unwrap_or("restricted");
        p.server_files = kube_harden::cis_files();
        for f in &mut p.server_files {
            if f.path.ends_with("/psa.yaml") {
                f.content = kube_harden::psa_config(level)?;
            }
        }
        p.notes.push(format!(
            "CIS profile written with Pod Security level {level}: images that run as root or need extra privileges are rejected outside kube-system. This is the profile, not a benchmark result; check it with `kube apple doctor NAME --cis`"
        ));
    }
    if !c.is_empty() {
        p.dropin = Some(c.render());
    }
    Ok(p)
}

fn kube_registry_embedded_all() -> Result<String> {
    crate::kube_registry::registries_yaml(&crate::kube_registry::RegistrySpec {
        embedded: vec!["*".into()],
        ..Default::default()
    })
}

// ---------------------------------------------------------------- applying

#[derive(Debug, Default, serde::Serialize)]
pub struct ApplyReport {
    pub wrote: Vec<String>,
    pub restarted: Vec<String>,
    /// Pinned add-ons installed after the settings were applied.
    pub installed: Vec<String>,
    pub notes: Vec<String>,
}

/// Writes the plan to the nodes: files first (and the sysctls, which `protect-kernel-defaults` needs before k3s starts),
/// then the drop-in, then restarts one node at a time, servers first, each one waited for. A failure stops at that node and
/// names what was already done; running the command again repeats the same writes.
pub async fn apply<R: Remote>(r: &R, p: &PlatformPlan, restart: bool) -> Result<ApplyReport> {
    let mut rep = ApplyReport { notes: p.notes.clone(), ..Default::default() };
    let nodes = r.nodes();
    let progress = |rep: &ApplyReport, e: anyhow::Error, node: &str| {
        anyhow::anyhow!("{node}: {e:#}; written so far: [{}]; restarted so far: [{}]; run the command again to finish", rep.wrote.join(", "), rep.restarted.join(", "))
    };
    for (node, role) in &nodes {
        for f in &p.all_files {
            put(r, node, &f.path, f.mode, &f.content).await.map_err(|e| progress(&rep, e, node))?;
            rep.wrote.push(format!("{node}:{}", f.path));
        }
        if *role != Role::Server {
            continue;
        }
        let res = async {
            for f in &p.server_files {
                put(r, node, &f.path, f.mode, &f.content).await?;
            }
            if !p.server_files.is_empty() {
                r.run(node, &format!(": fluxvm-op platform-sysctl; set -eu; sudo -n mkdir -p {SERVER_DIR}/logs; sudo -n sysctl -p /etc/sysctl.d/90-kubelet.conf >/dev/null"), None).await?;
            }
            if let Some(d) = &p.dropin {
                assert!(PLATFORM_DROPIN.starts_with(DROPIN_DIR));
                put(r, node, PLATFORM_DROPIN, "0600", d).await?;
            }
            anyhow::Ok(())
        }
        .await;
        res.map_err(|e| progress(&rep, e, node))?;
        for f in &p.server_files {
            rep.wrote.push(format!("{node}:{}", f.path));
        }
        if p.dropin.is_some() {
            rep.wrote.push(format!("{node}:{PLATFORM_DROPIN}"));
        }
    }
    if restart {
        for (node, role) in &nodes {
            let touched = !p.all_files.is_empty() || (*role == Role::Server && (p.dropin.is_some() || !p.server_files.is_empty()));
            if touched {
                restart_and_wait(r, node, *role).await.map_err(|e| progress(&rep, e, node))?;
                rep.restarted.push(node.clone());
            }
        }
    } else {
        rep.notes.push("nothing was restarted: k3s reads these files at start-up; restart each node (servers first) or run again with --restart".into());
    }
    Ok(rep)
}

#[cfg(test)]
pub(crate) mod fake {
    use super::*;
    use std::cell::RefCell;

    /// Records `(node, script, stdin)` and answers from `(substring, reply)` pairs; unanswered scripts return "".
    #[derive(Default)]
    pub struct FakeRemote {
        pub roles: Vec<(String, Role)>,
        pub log: RefCell<Vec<(String, String, Option<String>)>>,
        pub answers: RefCell<Vec<(String, String)>>,
        pub fail: RefCell<Vec<(String, String)>>,
    }

    impl FakeRemote {
        pub fn cluster(servers: usize, agents: usize) -> FakeRemote {
            let mut roles = vec![];
            for i in 1..=servers {
                roles.push((format!("c-s{i}"), Role::Server));
            }
            for i in 1..=agents {
                roles.push((format!("c-a{i}"), Role::Agent));
            }
            FakeRemote { roles, ..Default::default() }
        }
        pub fn answer(&self, contains: &str, reply: &str) {
            self.answers.borrow_mut().push((contains.into(), reply.into()));
        }
        pub fn fail_on(&self, contains: &str, msg: &str) {
            self.fail.borrow_mut().push((contains.into(), msg.into()));
        }
        /// `node: op-name` lines, for order assertions.
        pub fn ops(&self) -> Vec<String> {
            self.log
                .borrow()
                .iter()
                .map(|(n, s, _)| {
                    let op = s.strip_prefix(": fluxvm-op ").and_then(|x| x.split(';').next()).unwrap_or("-");
                    format!("{n}:{op}")
                })
                .collect()
        }
    }

    impl Remote for FakeRemote {
        fn nodes(&self) -> Vec<(String, Role)> {
            self.roles.clone()
        }
        async fn run(&self, node: &str, script: &str, stdin: Option<&[u8]>) -> Result<String> {
            self.log.borrow_mut().push((node.into(), script.into(), stdin.map(|b| String::from_utf8_lossy(b).into_owned())));
            if let Some((_, m)) = self.fail.borrow().iter().find(|(k, _)| script.contains(k.as_str())) {
                bail!("{m}");
            }
            if script.contains("is-active") {
                return Ok("active".into());
            }
            if script.contains("/readyz") {
                return Ok("ok".into());
            }
            Ok(self.answers.borrow().iter().find(|(k, _)| script.contains(k.as_str())).map(|(_, v)| v.clone()).unwrap_or_default())
        }
        async fn pause(&self, _: u64) {}
        fn stamp(&self) -> String {
            "20261122-120000".into()
        }
    }
}

#[cfg(test)]
mod tests {
    use super::fake::FakeRemote;
    use super::*;

    fn args() -> PlatformArgs {
        PlatformArgs::default()
    }

    #[test]
    fn no_flags_no_plan() {
        assert!(args().is_empty());
        let p = plan(&args(), None).unwrap();
        assert_eq!(p, PlatformPlan::default());
    }

    #[test]
    fn profiles() {
        assert_eq!(profile_disables("minimal").unwrap(), ["servicelb", "local-storage", "metrics-server"]);
        assert_eq!(profile_disables("metallb").unwrap(), ["servicelb"]);
        assert!(profile_disables("default").unwrap().is_empty());
        assert!(profile_disables("envoy-gateway").unwrap().is_empty());
        assert!(profile_disables("fancy").is_err());
    }

    #[test]
    fn envoy_gateway_profile_installs_and_disables_nothing() {
        let p = plan(&PlatformArgs { addons: Some("envoy-gateway".into()), ..args() }, None).unwrap();
        assert_eq!(p.install, ["envoy-gateway"]);
        assert!(p.disable.is_empty() && p.dropin.is_none());
        assert!(plan(&PlatformArgs { addons: Some("metallb".into()), ..args() }, None).unwrap().install.is_empty());
    }

    #[test]
    fn cilium_dropin_golden() {
        let a = PlatformArgs { cilium: true, cilium_kube_proxy_replacement: true, ..args() };
        let p = plan(&a, None).unwrap();
        assert_eq!(
            p.dropin.unwrap(),
            "# generated by `fluxctl kube addons`; edit with care\n\
             disable-kube-proxy: true\n\
             disable-network-policy: true\n\
             flannel-backend: none\n"
        );
        assert!(p.notes[0].contains("helm install cilium cilium/cilium --version 1.20.5"));
        assert!(p.notes[0].contains("kubeProxyReplacement=true"));
    }

    #[test]
    fn embedded_registry_without_file_writes_the_wildcard_mirror() {
        let a = PlatformArgs { embedded_registry: true, ..args() };
        let p = plan(&a, None).unwrap();
        assert!(p.dropin.as_ref().unwrap().contains("embedded-registry: true"));
        assert_eq!(p.all_files.len(), 1);
        assert_eq!(p.all_files[0].path, REGISTRIES_PATH);
        assert_eq!(p.all_files[0].mode, "0600");
        assert!(check_registries(&p.all_files[0].content).is_ok());
        assert!(p.all_files[0].content.contains("'*'") || p.all_files[0].content.contains("\"*\""));
    }

    #[test]
    fn embedded_registry_with_a_file_that_has_no_mirrors_is_refused() {
        let a = PlatformArgs { embedded_registry: true, ..args() };
        assert!(plan(&a, Some("configs:\n  r:\n    auth: {username: a, password: b}\n")).is_err());
        assert!(plan(&a, Some("mirrors:\n  docker.io:\n")).is_ok());
    }

    #[test]
    fn registries_file_checks() {
        assert!(check_registries("mirrors:\n  docker.io:\n    endpoint:\n      - https://m:5000\n").is_ok());
        assert!(check_registries("mirror:\n  a: b\n").is_err());
        assert!(check_registries("- a\n").is_err());
        assert!(check_registries("").is_err());
        assert!(check_registries("a: [").is_err());
    }

    #[test]
    fn cis_plan_has_files_config_and_the_chosen_psa_level() {
        let a = PlatformArgs { harden: Some("cis".into()), psa_level: Some("baseline".into()), ..args() };
        let p = plan(&a, None).unwrap();
        let d = p.dropin.unwrap();
        assert!(d.contains("protect-kernel-defaults: true") && d.contains("secrets-encryption: true"));
        let paths: Vec<_> = p.server_files.iter().map(|f| f.path.as_str()).collect();
        assert_eq!(paths, ["/etc/sysctl.d/90-kubelet.conf", "/var/lib/rancher/k3s/server/psa.yaml", "/var/lib/rancher/k3s/server/audit.yaml"]);
        assert!(p.server_files[1].content.contains("enforce: \"baseline\""));
        assert!(p.notes[0].contains("not a benchmark result"));
    }

    #[test]
    fn write_script_golden() {
        assert_eq!(
            write_file_script("/etc/rancher/k3s/registries.yaml", "0600"),
            ": fluxvm-op platform-write; set -eu; sudo -n install -D -m 0600 /dev/stdin /etc/rancher/k3s/registries.yaml"
        );
    }

    #[test]
    #[should_panic]
    fn write_script_refuses_odd_paths() {
        write_file_script("/etc/x; rm -rf /", "0600");
    }

    #[tokio::test]
    async fn apply_orders_files_before_config_before_restart_servers_first() {
        let a = PlatformArgs { harden: Some("cis".into()), embedded_registry: true, ..args() };
        let p = plan(&a, None).unwrap();
        let r = FakeRemote::cluster(2, 1);
        let rep = apply(&r, &p, true).await.unwrap();
        let ops = r.ops();
        // registries on every node, hardening files and the drop-in on servers only
        assert_eq!(ops.iter().filter(|o| o.ends_with("platform-write")).count(), 3 /*registries*/ + 2 * 4);
        assert_eq!(rep.restarted, ["c-s1", "c-s2", "c-a1"]);
        let first_restart = ops.iter().position(|o| o.ends_with("platform-restart")).unwrap();
        let last_write = ops.iter().rposition(|o| o.ends_with("platform-write")).unwrap();
        assert!(last_write < first_restart);
        let sysctl = ops.iter().position(|o| o == "c-s1:platform-sysctl").unwrap();
        assert!(sysctl < first_restart);
        // the drop-in comes after the files it points at
        let log = r.log.borrow();
        let audit = log.iter().position(|(_, s, _)| s.contains("/server/audit.yaml")).unwrap();
        let dropin = log.iter().position(|(_, s, _)| s.contains("40-fluxvm-platform.yaml")).unwrap();
        assert!(audit < dropin);
        // agents never get the server drop-in
        assert!(!log.iter().any(|(n, s, _)| n == "c-a1" && s.contains("40-fluxvm-platform")));
    }

    #[tokio::test]
    async fn apply_without_restart_says_so() {
        let p = plan(&PlatformArgs { cilium: true, ..args() }, None).unwrap();
        let r = FakeRemote::cluster(1, 0);
        let rep = apply(&r, &p, false).await.unwrap();
        assert!(rep.restarted.is_empty());
        assert!(rep.notes.iter().any(|n| n.contains("nothing was restarted")));
        assert!(!r.ops().iter().any(|o| o.ends_with("platform-restart")));
    }

    #[tokio::test]
    async fn apply_failure_names_the_node_and_stops() {
        let p = plan(&PlatformArgs { cilium: true, ..args() }, None).unwrap();
        let r = FakeRemote::cluster(2, 0);
        r.fail_on("platform-restart", "boom");
        let e = apply(&r, &p, true).await.unwrap_err().to_string();
        assert!(e.contains("c-s1: boom") && e.contains("run the command again"), "{e}");
        assert!(!r.ops().iter().any(|o| o.starts_with("c-s2:platform-restart")));
    }
}
